command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$branch="work/current-release-packaging-20261005"
$candidate="8283ece6c4348a751f487a64230e1bc149a47a2f"
Set-Location -LiteralPath $repo
& git fetch origin $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("packaging-shutdown-root-cause-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & python -X utf8 tools\winui\check_python_static.py tools\winui\diagnose_installed_shutdown.py tests\winui\test_installed_lifecycle.py tests\winui\test_installer_contract.py
  if($LASTEXITCODE -ne 0){throw "shutdown harness static check failed"}
  & python -X utf8 tests\winui\test_installer_contract.py
  if($LASTEXITCODE -ne 0){throw "installer contract failed"}

  & .\clean.bat build
  if($LASTEXITCODE -ne 0){throw "clean build output failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 packaging\provenance.py --write
  if($LASTEXITCODE -ne 0){throw "payload provenance generation failed"}
  & python -X utf8 packaging\provenance.py --check
  if($LASTEXITCODE -ne 0){throw "payload provenance verification failed"}

  & .\package.bat Release
  if($LASTEXITCODE -ne 0){throw "current Release package build failed"}

  & python -X utf8 tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "bounded installed lifecycle failed"}

  Write-Host "PACKAGING_SHUTDOWN_ROOT_CAUSE_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
